public final class HibernateAccess {
    private static final int ENTITY_LIMIT = 500, ATTRIBUTE_LIMIT = 5000, FUNCTION_LIMIT = 512;
    private static final int SELECTION_LIMIT = 128, PARAMETER_LIMIT = 256, COLUMN_LIMIT = 64;
