package rocketbrain.observer;

import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/** Small bounded JSON codec, without reflection, polymorphic loading or executable expressions. */
final class Json {
    private Json(){}
    static Map<String,Object> object(String input){Object value=new Reader(input).read();if(!(value instanceof Map<?,?>))throw new IllegalArgumentException("JSON object required");@SuppressWarnings("unchecked")Map<String,Object> map=(Map<String,Object>)value;return map;}
    static String encode(Object value){StringBuilder out=new StringBuilder();write(value,out,0);if(out.length()>2_000_000)throw new IllegalArgumentException("Response limit exceeded");return out.toString();}
    private static void write(Object value,StringBuilder out,int depth){if(depth>32||out.length()>2_000_000)throw new IllegalArgumentException("JSON limit exceeded");if(value==null)out.append("null");else if(value instanceof Boolean||value instanceof Number)out.append(value);else if(value instanceof String text){out.append('"');for(int i=0;i<text.length();i++){char c=text.charAt(i);switch(c){case '"'->out.append("\\\"");case '\\'->out.append("\\\\");case '\n'->out.append("\\n");case '\r'->out.append("\\r");case '\t'->out.append("\\t");default->{if(c<32)out.append(String.format("\\u%04x",(int)c));else out.append(c);}}}out.append('"');}else if(value instanceof Map<?,?> map){out.append('{');boolean comma=false;for(var entry:map.entrySet()){if(!(entry.getKey() instanceof String))throw new IllegalArgumentException("JSON key required");if(comma)out.append(',');comma=true;write(entry.getKey(),out,depth+1);out.append(':');write(entry.getValue(),out,depth+1);}out.append('}');}else if(value instanceof Iterable<?> list){out.append('[');boolean comma=false;for(var item:list){if(comma)out.append(',');comma=true;write(item,out,depth+1);}out.append(']');}else throw new IllegalArgumentException("Non-JSON metadata rejected");}
    private static final class Reader {
        final String text;int at,nodes;
        Reader(String text){if(text.length()>65536)throw new IllegalArgumentException("JSON size limit");this.text=text;}
        Object read(){Object value=value(0);space();if(at!=text.length())throw new IllegalArgumentException("Trailing JSON");return value;}
        void space(){while(at<text.length()&&Character.isWhitespace(text.charAt(at)))at++;}
        Object value(int depth){space();if(depth>24||++nodes>4096||at>=text.length())throw new IllegalArgumentException("JSON limit or missing value");char c=text.charAt(at);if(c=='"')return string();if(c=='{'){at++;Map<String,Object> map=new LinkedHashMap<>();space();if(take('}'))return map;for(;;){space();String key=string();if(map.containsKey(key))throw new IllegalArgumentException("Duplicate JSON key");space();if(!take(':'))throw new IllegalArgumentException("JSON colon required");map.put(key,value(depth+1));space();if(take('}'))return map;if(!take(','))throw new IllegalArgumentException("JSON comma required");}}if(c=='['){at++;List<Object> list=new ArrayList<>();space();if(take(']'))return list;for(;;){list.add(value(depth+1));space();if(take(']'))return list;if(!take(','))throw new IllegalArgumentException("JSON comma required");}}for(var item:Map.of("true",true,"false",false).entrySet())if(text.startsWith(item.getKey(),at)){at+=item.getKey().length();return item.getValue();}if(text.startsWith("null",at)){at+=4;return null;}int start=at;if(c=='-')at++;while(at<text.length()&&Character.isDigit(text.charAt(at)))at++;if(at==start||at==start+1&&c=='-')throw new IllegalArgumentException("Invalid JSON value");String number=text.substring(start,at);if(!number.matches("-?(0|[1-9][0-9]*)"))throw new IllegalArgumentException("Integer JSON expected");return Long.parseLong(number);}
