        String string(){if(!take('"'))throw new IllegalArgumentException("JSON string required");StringBuilder out=new StringBuilder();while(at<text.length()){char c=text.charAt(at++);if(c=='"')return out.toString();if(c<32)throw new IllegalArgumentException("JSON control character");if(c=='\\'){if(at>=text.length())throw new IllegalArgumentException("JSON escape");c=text.charAt(at++);switch(c){case '"','\\','/'->out.append(c);case 'b'->out.append('\b');case 'f'->out.append('\f');case 'n'->out.append('\n');case 'r'->out.append('\r');case 't'->out.append('\t');case 'u'->{if(at+4>text.length())throw new IllegalArgumentException("JSON Unicode");out.append((char)Integer.parseInt(text.substring(at,at+4),16));at+=4;}default->throw new IllegalArgumentException("JSON escape");}}else out.append(c);}throw new IllegalArgumentException("Unterminated JSON string");}
